//! Wire types shared by the app and the sidecar.
//!
//! The Rust types are the truth; `just gen-protocol` writes them to
//! `sidecar/src/protocol.ts` and a test fails when that file is stale.

pub mod messages;
pub mod nodes;
pub mod tools;

pub use messages::*;
pub use nodes::*;
pub use tools::*;

use ts_rs::{Config, TS};

/// Path of the generated file, relative to the workspace root.
pub const TS_OUTPUT: &str = "sidecar/src/protocol.ts";

/// Render every protocol type as one TypeScript module.
#[must_use]
pub fn typescript() -> String {
    let cfg = Config::new().with_large_int("number");
    let mut out = String::from(
        "// GENERATED by `just gen-protocol` from crates/berth-protocol. Do not edit.\n\
         /* eslint-disable */\n\n",
    );

    macro_rules! decls {
        ($($t:ty),* $(,)?) => {
            $(
                out.push_str("export ");
                out.push_str(&<$t as TS>::decl(&cfg));
                out.push_str("\n\n");
            )*
        };
    }

    decls!(
        serde_json::Value,
        // nodes
        OriginKind,
        Origin,
        FollowUp,
        DiffSide,
        DiffPreset,
        ReviewComment,
        FileRef,
        Prompt,
        Question,
        FindingLevel,
        FindingAction,
        Finding,
        Review,
        Rewind,
        Reopened,
        Decision,
        Summary,
        OutcomeKind,
        Outcome,
        SubagentSpawn,
        BranchStatus,
        CollectResults,
        Artifact,
        NodeKind,
        NodePayload,
        // tools
        ToolName,
        FollowUpInput,
        RecordDecisionInput,
        AskUserInput,
        WriteSummaryInput,
        RecordOutcomeInput,
        RequestSlotInput,
        RequestSlotResult,
        PresentArtifactInput,
        FindingInput,
        PresentReviewInput,
        // messages
        ConnectorSkill,
        SessionStart,
        Effort,
        SessionConfigure,
        ModelChoice,
        SessionModels,
        SessionsList,
        PastSession,
        SessionsListed,
        SessionResume,
        SessionTurn,
        TurnAttachment,
        QuestionAnswer,
        ReviewAnswer,
        SlotRequestResolved,
        AppToSidecar,
        SessionStarted,
        RawEvent,
        NodeDecision,
        NodeQuestion,
        NodeSummary,
        NodeOutcome,
        NodeArtifact,
        NodeReview,
        BranchSpawned,
        BranchCollected,
        SlotRequest,
        TerminalKind,
        RoundEnded,
        SessionCost,
        SessionError,
        SidecarToApp,
        AppMessage,
        SidecarMessage,
    );

    out.push_str(&format!(
        "export const MCP_SERVER_NAME = {MCP_SERVER_NAME:?} as const;\n\n"
    ));
    out.push_str("export const TOOLS: Record<ToolName, { terminal: boolean; subagent: boolean; description: string }> = {\n");
    for tool in ToolName::ALL {
        out.push_str(&format!(
            "  {}: {{ terminal: {}, subagent: {}, description: {:?} }},\n",
            tool.as_str(),
            tool.is_terminal(),
            tool.allowed_in_subagent(),
            tool.description()
        ));
    }
    out.push_str("};\n");
    out
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used, clippy::expect_used)]

    use super::*;
    use std::path::PathBuf;

    fn roundtrip_app(msg: &AppMessage) {
        let line = serde_json::to_string(msg).unwrap();
        let back: AppMessage = serde_json::from_str(&line).unwrap();
        assert_eq!(&back, msg, "{line}");
    }

    fn roundtrip_sidecar(msg: &SidecarMessage) {
        let line = serde_json::to_string(msg).unwrap();
        let back: SidecarMessage = serde_json::from_str(&line).unwrap();
        assert_eq!(&back, msg, "{line}");
    }

    #[test]
    fn app_messages_have_flat_envelope() {
        let msg = AppMessage {
            id: "1".into(),
            body: AppToSidecar::SessionTurn(SessionTurn {
                text: "hi".into(),
                attachments: vec![],
            }),
        };
        let v: serde_json::Value = serde_json::to_value(&msg).unwrap();
        assert_eq!(
            v,
            serde_json::json!({"id": "1", "type": "session.turn", "text": "hi"})
        );
        roundtrip_app(&msg);
        roundtrip_app(&AppMessage {
            id: "2".into(),
            body: AppToSidecar::SessionInterrupt,
        });
        let start = SessionStart {
            workflow_id: "wf".into(),
            cwd: "/tmp/x".into(),
            system_prompt: String::new(),
            env: [("A".to_owned(), "b".to_owned())].into(),
            allowed_tools: vec![],
            connector_skills: vec![ConnectorSkill {
                name: "linear".into(),
                description: "Linear CLI".into(),
            }],
            model: None,
            effort: Some(Effort::Xhigh),
        };
        roundtrip_app(&AppMessage {
            id: "3".into(),
            body: AppToSidecar::SessionResume(SessionResume {
                claude_session_id: "s".into(),
                resume_at: Some("u-41".into()),
                start,
            }),
        });
        let parsed: AppMessage =
            serde_json::from_str(r#"{"id":"4","type":"session.stop"}"#).unwrap();
        assert_eq!(parsed.body, AppToSidecar::SessionStop);
    }

    #[test]
    fn model_and_effort_on_the_wire() {
        // A reset goes out as explicit nulls, so the sidecar knows to clear it.
        let msg = AppMessage {
            id: "5".into(),
            body: AppToSidecar::SessionConfigure(SessionConfigure {
                model: Some("opus".into()),
                effort: None,
            }),
        };
        assert_eq!(
            serde_json::to_value(&msg).unwrap(),
            serde_json::json!({"id": "5", "type": "session.configure", "model": "opus", "effort": null})
        );
        roundtrip_app(&msg);
        let models: SidecarMessage = serde_json::from_value(serde_json::json!({
            "id": "c",
            "type": "session.models",
            "models": [{"value": "opus", "display_name": "Opus", "efforts": ["low", "xhigh", "max"]}]
        }))
        .unwrap();
        let SidecarToApp::SessionModels(m) = &models.body else {
            panic!("not session.models");
        };
        assert_eq!(
            m.models[0].efforts,
            [Effort::Low, Effort::Xhigh, Effort::Max]
        );
        assert_eq!(m.models[0].description, "");
        roundtrip_sidecar(&models);
        assert_eq!(Effort::parse("xhigh"), Some(Effort::Xhigh));
        assert_eq!(Effort::parse("turbo"), None);
    }

    #[test]
    fn sidecar_messages_roundtrip() {
        roundtrip_sidecar(&SidecarMessage {
            id: "a".into(),
            reply_to: Some("1".into()),
            body: SidecarToApp::SessionStarted(SessionStarted {
                claude_session_id: "abc".into(),
            }),
        });
        roundtrip_sidecar(&SidecarMessage {
            id: "b".into(),
            reply_to: None,
            body: SidecarToApp::RawEvent(RawEvent {
                seq: 7,
                kind: "assistant".into(),
                json: serde_json::json!({"type": "assistant", "n": 1.5, "big": 12_345_678_901_u64}),
                branch_id: Some("br".into()),
            }),
        });
        roundtrip_sidecar(&SidecarMessage {
            id: "c".into(),
            reply_to: None,
            body: SidecarToApp::NodeDecision(NodeDecision {
                decision: Decision {
                    title: "Use sqlite".into(),
                    rationale: "simple".into(),
                    affects: vec!["a.rs".into()],
                    reversible: true,
                },
                branch_id: None,
            }),
        });
        roundtrip_sidecar(&SidecarMessage {
            id: "d".into(),
            reply_to: None,
            body: SidecarToApp::NodeOutcome(NodeOutcome {
                outcome: Outcome {
                    kind: OutcomeKind::Pr,
                    r#ref: "https://github.com/o/r/pull/1".into(),
                    summary: "done".into(),
                    follow_ups: vec![],
                },
            }),
        });
        let v: serde_json::Value = serde_json::from_str(
            r#"{"id":"e","type":"round.ended","terminal_kind":"write_summary","cost_usd":0.5,"duration_ms":10,"nudges":0}"#,
        )
        .unwrap();
        let m: SidecarMessage = serde_json::from_value(v).unwrap();
        assert!(matches!(m.body, SidecarToApp::RoundEnded(_)));
    }

    #[test]
    fn attachments_and_artifacts_roundtrip() {
        roundtrip_app(&AppMessage {
            id: "t".into(),
            body: AppToSidecar::SessionTurn(SessionTurn {
                text: "see image".into(),
                attachments: vec![TurnAttachment {
                    path: "/w/a.png".into(),
                    mime: "image/png".into(),
                }],
            }),
        });
        // `attachments` is optional on the wire.
        let parsed: AppMessage =
            serde_json::from_str(r#"{"id":"u","type":"session.turn","text":"hi"}"#).unwrap();
        assert_eq!(
            parsed.body,
            AppToSidecar::SessionTurn(SessionTurn {
                text: "hi".into(),
                attachments: vec![]
            })
        );
        roundtrip_sidecar(&SidecarMessage {
            id: "a".into(),
            reply_to: None,
            body: SidecarToApp::NodeArtifact(NodeArtifact {
                artifact_id: "art".into(),
                path: "/w/shot.png".into(),
                title: "Login page".into(),
                description: None,
                size_bytes: 12_345,
            }),
        });
        let node = NodePayload::Artifact(Artifact {
            artifact_id: "art".into(),
            title: "Login page".into(),
            description: Some("after the fix".into()),
            file: FileRef {
                id: "art".into(),
                name: "shot.png".into(),
                mime: "image/png".into(),
                size_bytes: 12_345,
                slot_path: Some("/w/shot.png".into()),
                stored: None,
                thumbnail: None,
            },
            error: None,
        });
        let json = node.payload_json().unwrap();
        assert_eq!(NodePayload::from_parts(node.kind(), &json).unwrap(), node);
    }

    #[test]
    fn reviews_roundtrip() {
        let msg: SidecarMessage = serde_json::from_value(serde_json::json!({
            "id": "r",
            "type": "node.review",
            "review_id": "rv",
            "findings": [
                {"level": "high", "title": "Unchecked unwrap", "detail": "Panics on empty input.",
                 "path": "src/parse.rs", "line": 42, "suggested": "fix"},
                {"level": "low", "title": "Naming", "detail": "Shadows std.", "suggested": "decide"}
            ]
        }))
        .unwrap();
        let SidecarToApp::NodeReview(r) = &msg.body else {
            panic!("not node.review");
        };
        assert_eq!(r.findings[0].level, FindingLevel::High);
        assert_eq!(r.findings[1].suggested, FindingAction::Decide);
        assert_eq!(r.findings[1].line, None);
        roundtrip_sidecar(&msg);
        roundtrip_app(&AppMessage {
            id: "a".into(),
            body: AppToSidecar::ReviewAnswer(ReviewAnswer {
                review_id: "rv".into(),
                text: "1. fix it".into(),
            }),
        });
        let node = NodePayload::Review(Review {
            review_id: "rv".into(),
            summary: None,
            findings: vec![Finding {
                level: FindingLevel::Mid,
                title: "t".into(),
                detail: "d".into(),
                path: None,
                line: None,
                suggested: FindingAction::Dismiss,
                choice: Some(FindingAction::Decide),
                note: Some("keep it, rename later".into()),
            }],
            answered_at: Some(1),
        });
        let json = node.payload_json().unwrap();
        assert_eq!(NodePayload::from_parts(node.kind(), &json).unwrap(), node);
        assert!(ToolName::PresentReview.is_terminal());
        assert!(!ToolName::PresentReview.allowed_in_subagent());
    }

    #[test]
    fn session_history_on_the_wire() {
        roundtrip_app(&AppMessage {
            id: "h".into(),
            body: AppToSidecar::SessionsList(SessionsList {
                dir: "/repo".into(),
            }),
        });
        let listed: SidecarMessage = serde_json::from_value(serde_json::json!({
            "id": "l",
            "reply_to": "h",
            "type": "sessions.listed",
            "sessions": [{"session_id": "s", "title": "Fix login", "last_modified": 1_700_000_000_000_i64}]
        }))
        .unwrap();
        let SidecarToApp::SessionsListed(l) = &listed.body else {
            panic!("not sessions.listed");
        };
        assert_eq!(l.sessions[0].cwd, None);
        roundtrip_sidecar(&listed);
        assert_eq!(OriginKind::Session.as_str(), "session");
    }

    #[test]
    fn node_payload_parts_roundtrip() {
        let p = NodePayload::Outcome(Outcome {
            kind: OutcomeKind::None,
            r#ref: String::new(),
            summary: "s".into(),
            follow_ups: vec![],
        });
        let json = p.payload_json().unwrap();
        assert!(json.contains(r#""ref":"""#), "{json}");
        assert_eq!(NodePayload::from_parts(p.kind(), &json).unwrap(), p);
        for k in NodeKind::ALL {
            assert_eq!(NodeKind::parse(k.as_str()), Some(k));
        }
    }

    #[test]
    fn generated_typescript_is_fresh() {
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .join(TS_OUTPUT);
        let on_disk = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(
            on_disk == typescript(),
            "{} is stale; run `just gen-protocol`",
            path.display()
        );
    }
}
